document.querySelectorAll('details').forEach(detail=>{const content=detail.querySelector('.content');if(detail.open)content.style.maxHeight=content.scrollHeight+'px';detail.addEventListener('toggle',()=>{if(detail.open)content.style.maxHeight=content.scrollHeight+'px';else content.style.maxHeight=0});window.addEventListener('resize',()=>{if(detail.open)content.style.maxHeight=content.scrollHeight+'px'})});window.onclick=function(event){const modal=document.getElementById('privacyModal');if(event.target==modal){modal.style.display='none'}}
function openModalPrivacy(){document.getElementById('privacyModal').style.display='block'}
function closeModalPrivacy(){document.getElementById('privacyModal').style.display='none'}
window.onclick=function(event){const modal=document.getElementById('privacyModalDesk');if(event.target==modal){modal.style.display='none'}}
function openModalPrivacyDesk(){document.getElementById('privacyModalDesk').style.display='block'}
function closeModalPrivacyDesk(){document.getElementById('privacyModalDesk').style.display='none'}
