function openModalTermsDesk(){document.getElementById('termsModalDesk').style.display='block'}
function closeModalTermsDesk(){document.getElementById('termsModalDesk').style.display='none'}
let playerBefore,playerBeforeMobile,playerAfter;function loadVideoButtonBefore(){const container=document.querySelector('.video-wrap-before');document.getElementById("video-inner-before").style.display="none";container.classList.add("playing");if(window.matchMedia("(max-width: 768px)").matches){if(!playerBeforeMobile||typeof playerBeforeMobile.playVideo!=="function"){playerBeforeMobile=new YT.Player('player-mobile',{height:'360',width:'640',videoId:'5jXNy_RAKxw',playerVars:{'autoplay':1,'mute':1,'playsinline':1,'controls':1,'rel':0,'modestbranding':1},events:{'onReady':()=>{playerBeforeMobile.playVideo()},'onStateChange':onPlayerStateChange}})}}else{if(!playerBefore||typeof playerBefore.playVideo!=="function"){playerBefore=new YT.Player('player',{height:'360',width:'640',videoId:'5jXNy_RAKxw',playerVars:{'autoplay':1,'mute':1,'playsinline':1,'controls':1,'rel':0,'modestbranding':1},events:{'onReady':()=>{console.log("Player pronto!");playerBefore.playVideo()},'onStateChange':onPlayerStateChange}})}
playerBefore.playVideo()}
function onPlayerStateChange(event){if(event.data===YT.PlayerState.ENDED){document.getElementById("video-inner-before").style.display='inline-block'}}}
function loadVideoButtonAfter(){const container=document.querySelector('.video-wrap-after');document.getElementById("video-inner-after").style.display="none";container.classList.add("playing");if(window.matchMedia("(max-width: 768px)").matches){if(!playerAfter||typeof playerAfter.playVideo!=="function"){playerAfter=new YT.Player('player-after',{height:'360',width:'640',videoId:'K-_XRC-SHnQ',playerVars:{'autoplay':1,'mute':1,'playsinline':1,'controls':1,'rel':0,'modestbranding':1},events:{'onReady':()=>{console.log("Player pronto!");playerAfter.playVideo()},'onStateChange':onPlayerStateChange}})}}else{if(!playerAfter||typeof playerAfter.playVideo!=="function"){playerAfter=new YT.Player('player-after',{height:'360',width:'640',videoId:'K-_XRC-SHnQ',playerVars:{'autoplay':1,'mute':1,'playsinline':1,'controls':1,'rel':0,'modestbranding':1},events:{'onReady':()=>{playerAfter.playVideo()},'onStateChange':onPlayerStateChange}})}
playerAfter.playVideo()}
function onPlayerStateChange(event){if(event.data===YT.PlayerState.ENDED){document.getElementById("video-inner-after").style.display='inline-block'}}}
window.addEventListener('load',function(){const loader=document.getElementById('loader');setTimeout(()=>{loader.classList.add('hidden')},800)})